contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address newOwner) public payable {
        address originalOwner = c.owner(); if (__ESBMC_reverted()) return;

        bool reverted;
        bool success;
        bool s = c.setOwner(newOwner); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
            success = false;
        } else {
            reverted = false;
            success = s;
        }

        address finalOwner = c.owner(); if (__ESBMC_reverted()) return;

        assert(
            (reverted && finalOwner == originalOwner && !success) ||
            (!reverted && finalOwner == newOwner && success)
        );
    }
}

